#!/usr/bin/env node
/**
 * Copy the published research figures out of the research repository.
 *
 * The figures are generated by analysis scripts in the RE:REASON research
 * repository and are the only binary artefacts this site ships. They are copied
 * **byte for byte**: no re-encoding, no cropping, no colour adjustment. Chart
 * values, axes and labels are evidence and are never altered for presentation.
 *
 * Because a copy can silently drift from its source, every file's SHA-256 is
 * recorded in the generated manifest. Re-running the script reports any figure
 * whose source has changed, so a stale copy is visible rather than assumed.
 *
 * Usage:
 *   node scripts/sync-figures.mjs                 # write files and manifest
 *   node scripts/sync-figures.mjs --check         # verify only, exit 1 on drift
 *   RE_REASON_REPO=/path/to/re-reason node scripts/sync-figures.mjs
 */

import { createHash } from 'node:crypto';
import { mkdir, readFile, writeFile, access } from 'node:fs/promises';
import { dirname, join, resolve } from 'node:path';
import { fileURLToPath } from 'node:url';

const ROOT = join(dirname(fileURLToPath(import.meta.url)), '..');
const SOURCE_REPO =
  process.env.RE_REASON_REPO ?? resolve(ROOT, '..', 're-reason');
const SOURCE_DIR = join(SOURCE_REPO, 'docs', 'reports', 'figures');
const OUT_DIR = join(ROOT, 'public', 'figures');
const MANIFEST = join(OUT_DIR, 'SOURCES.json');

/**
 * The published set.
 *
 * Each entry must name the report that specifies the figure and states what it
 * plots. A figure is only published here once its meaning, axes and generating
 * report have been read and the plot has been checked against the report's
 * description — a filename is not provenance, and neither is a figure that
 * merely looks plausible.
 *
 * Two figures that pass the filename test currently fail that check and are
 * deliberately NOT published; see docs/figures.md for the audit.
 */
const PUBLISHED = [
  // Experiment G — docs/reports/experiment_g_add_commit_gap.md §"Required Figures"
  'experiment_g_gate_vs_commit_acc.png',
  'experiment_g_confound_strata.png',
  'experiment_g_oracle_vs_committed.png',
  // Mechanism QA diagnostic — docs/reports/mechanism_qa_diagnostic.md §10
  '06_register_probe_accuracy_over_time.png',
  '07_retention_vs_intervening_steps.png',
  '08_failure_rate_by_operation_type.png',
];

const sha256 = (buf) => createHash('sha256').update(buf).digest('hex');

async function main() {
  const checkOnly = process.argv.includes('--check');

  try {
    await access(SOURCE_DIR);
  } catch {
    console.error(`Research figure directory not found: ${SOURCE_DIR}`);
    console.error('Set RE_REASON_REPO to the research repository root and retry.');
    process.exit(1);
  }

  await mkdir(OUT_DIR, { recursive: true });

  let previous = null;
  try {
    previous = JSON.parse(await readFile(MANIFEST, 'utf8'));
  } catch {
    /* first run */
  }
  const previousByFile = new Map((previous?.figures ?? []).map((f) => [f.file, f]));

  const manifest = [];
  const drift = [];

  for (const file of PUBLISHED) {
    const src = join(SOURCE_DIR, file);
    let bytes;
    try {
      bytes = await readFile(src);
    } catch {
      console.error(`  MISSING SOURCE  ${file}`);
      process.exitCode = 1;
      continue;
    }

    const hash = sha256(bytes);
    const before = previousByFile.get(file);

    if (before && before.sha256 !== hash) {
      drift.push(file);
    }

    if (!checkOnly) {
      await writeFile(join(OUT_DIR, file), bytes);
    }

    manifest.push({ file, bytes: bytes.length, sha256: hash });
  }

  if (!checkOnly) {
    // Remove anything previously published that is no longer in the set, so a
    // withdrawn figure cannot linger in public/ after the manifest drops it.
    const { readdir, unlink } = await import('node:fs/promises');
    const keep = new Set([...PUBLISHED, 'SOURCES.json']);
    for (const existing of await readdir(OUT_DIR)) {
      if (!keep.has(existing)) {
        await unlink(join(OUT_DIR, existing));
        console.log(`  removed withdrawn figure  ${existing}`);
      }
    }

    await writeFile(
      MANIFEST,
      JSON.stringify(
        {
          note:
            'SHA-256 of every published research figure, copied byte for byte from the RE:REASON research repository. Regenerate with `node scripts/sync-figures.mjs`. A hash change means the upstream figure was regenerated and the interpretation on the site may need re-checking against its report.',
          source: 're-reason/docs/reports/figures',
          synced: new Date().toISOString().slice(0, 10),
          figures: manifest,
        },
        null,
        2,
      ) + '\n',
    );
  }

  console.log(
    `${checkOnly ? 'verified' : 'synced'} ${manifest.length}/${PUBLISHED.length} figures -> public/figures/`,
  );
  if (drift.length) {
    console.log(`\nUPSTREAM CHANGED since the last sync (re-read the report before publishing):`);
    for (const f of drift) console.log(`  ${f}`);
    process.exitCode = 1;
  }
}

main().catch((err) => {
  console.error('FAILED:', err.message);
  process.exit(1);
});
